<?php require_once 'db_connect.php'; $id=trim($_GET['id']??''); if($id==='')die('Invalid student ID'); $stmt=$conn->prepare('SELECT * FROM students WHERE id=?');$stmt->bind_param('s',$id);$stmt->execute();$row=$stmt->get_result()->fetch_assoc(); ?>
<!doctype html><html><head><title>Student Details</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><div class="nav"><a href="index.php">Back</a></div><?php if(!$row):?><p>Student not found.</p><?php else:?><h2>Student Details</h2><div class="card"><strong>Student ID:</strong><span><?=htmlspecialchars($row['id'])?></span><strong>Full Name:</strong><span><?=htmlspecialchars($row['first_name'].' '.($row['middle_name']??'').' '.$row['last_name'])?></span><strong>Birthday:</strong><span><?=htmlspecialchars($row['birthday'])?></span><strong>Sex:</strong><span><?=htmlspecialchars($row['sex'])?></span><strong>Email:</strong><span><?=htmlspecialchars($row['email'])?></span><strong>Student Number:</strong><span><?=htmlspecialchars($row['student_number']??'')?></span><strong>Program:</strong><span><?=htmlspecialchars($row['program']??'')?></span><strong>Enrolment Date:</strong><span><?=htmlspecialchars($row['enrolment_date'])?></span><strong>Created At:</strong><span><?=htmlspecialchars($row['created_at'])?></span></div><?php endif;?></div></body></html>